with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('holde fast', 'phrase', '8b1604ec-0305-5ce6-bdd4-7fccd3f03707', 1, 'verb', null, 'твердо триматися (думки, рішення)', 'Hun holder fast i sin mening om filmen.', 'Вона не змінює своєї думки про фільм.'), ('stå fast', 'phrase', '6e755c97-d15d-556f-8620-9f17f83bf935', 1, 'verb', null, 'стояти на своєму', 'Hun står fast på sin beslutning.', 'Вона твердо стоїть на своєму рішенні.'), ('være tæt på', 'phrase', '12a302d2-df21-5dd6-9486-2fb102d1d518', 1, 'verb', null, 'бути близько до (чогось)', 'Huset er tæt på skoven.', 'Будинок розташований близько до лісу.'), ('være tæt på', 'phrase', 'de0659cd-14a6-5cdd-a4a4-caf467412779', 2, 'verb', null, 'мало не (зробити щось)', 'Jeg var tæt på at græde.', 'Я була на межі сліз.'), ('føle med', 'phrase', 'd0346ab3-6c83-5607-998a-13c820fca439', 1, 'verb', null, 'співчувати', 'Jeg føler med dig i den svære tid.', 'Я співчуваю тобі в цей важкий час.'), ('hjælpe mod', 'phrase', 'b1f859c0-38a5-5723-993c-740c7847d135', 1, 'verb', null, 'допомагати проти (болю, хвороби)', 'Den her medicin hjælper mod min hovedpine.', 'Ці ліки допомагають мені від головного болю.'), ('flytte tilbage', 'phrase', '6f925739-4f43-59b4-8fe9-72904d377a6d', 1, 'verb', null, 'переїжджати назад', 'De flyttede tilbage til København sidste år.', 'Минулого року вони переїхали назад до Копенгагена.'), ('ændre på', 'phrase', 'd6ea7d3f-0db2-53ba-ad26-1ac3ea71487b', 1, 'verb', null, 'змінювати (щось)', 'Jeg vil gerne ændre på aftalen.', 'Я хотів би змінити угоду.'), ('holde sig væk', 'phrase', '246d28ce-8e43-5d18-8f2d-78aea0941e42', 1, 'verb', null, 'триматися подалі (не наближатися)', 'Du skal holde dig væk fra den gamle bygning.', 'Тобі потрібно триматися подалі від старої будівлі.'), ('gå i krig', 'phrase', 'c559bf10-ecad-5249-a561-df3361261a48', 1, 'verb', null, 'вступати у війну (починати воєнні дії)', 'Landet gik i krig efter mange års fred.', 'Країна вступила у війну після багатьох років миру.'), ('falde fra hinanden', 'phrase', '6091d01d-e695-549d-9e67-6e9052c1965b', 1, 'verb', null, 'розвалюватися (про предмет)', 'Den gamle stol falder fra hinanden, når du sætter dig på den.', 'Старий стілець розвалюється, коли на нього сідаєш.'), ('søge hjælp', 'phrase', '33053f31-1e24-5b43-893a-b2018575c70f', 1, 'verb', null, 'звертатися по допомогу', 'Hun søger hjælp hos sin læge.', 'Вона звертається по допомогу до свого лікаря.'), ('svare ja', 'phrase', '5475b414-11fe-510d-81d5-6f0c22b7d606', 1, 'verb', null, 'відповісти згодою', 'Hun svarede ja til invitationen med det samme.', 'Вона одразу погодилася на запрошення.'), ('gå sig en tur', 'phrase', '118bd8d6-564a-5a31-bd99-d2b04108098b', 1, 'verb', null, 'піти на прогулянку', 'Jeg går mig en tur hver aften efter aftensmad.', 'Щовечора після вечері я виходжу прогулятися.'), ('mene det alvorligt', 'phrase', '8273e68f-2069-56bf-8e68-f049e52dee5d', 1, 'verb', null, 'говорити серйозно (не жартувати)', 'Jeg mener det alvorligt, når jeg siger, at jeg flytter.', 'Я серйозно кажу, що переїжджаю.'), ('være i tvivl', 'phrase', 'faaaaf35-adca-5299-801a-466a32f7d44e', 1, 'verb', null, 'сумніватися', 'Jeg er i tvivl om svaret er rigtigt.', 'Я сумніваюся, чи правильна відповідь.'), ('stemme imod', 'phrase', 'c3b285df-7599-5cee-b3d7-c777b4db658e', 1, 'verb', null, 'голосувати проти', 'De fleste i udvalget stemte imod forslaget.', 'Більшість членів комітету проголосувала проти цієї пропозиції.'), ('skifte fra', 'phrase', 'ff0aaa8e-d2b0-59a2-9629-44206b7dcfc0', 1, 'verb', null, 'перемикатися (з одного на інше)', 'Jeg skifter fra kaffe til te om aftenen.', 'Ввечері я перемикаюся з кави на чай.'), ('kunne stå inde for', 'phrase', 'fe0709aa-0b2d-5b18-b728-a6b5aa9b72d5', 1, 'verb', null, 'ручатися за', 'Jeg kan stå inde for kvaliteten af maden her.', 'Я можу ручатися за якість їжі тут.'), ('holde en pause', 'phrase', '902faf16-bf28-52fe-ac3b-bc68bc49eab0', 1, 'verb', null, 'робити перерву', 'Jeg holder en pause fra arbejdet.', 'Я беру перерву в роботі.'), ('træde frem', 'phrase', '1d4fe771-7361-5272-b922-cf76ef23dc75', 1, 'verb', null, 'виступати (виходити вперед)', 'Hun trådte frem fra mængden og smilede.', 'Вона вийшла з натовпу і посміхнулася.'), ('træde til', 'phrase', '5ffc86c8-1624-57f5-a7ca-6945a7d44df7', 1, 'verb', null, 'втручатися, приходити на допомогу', 'Brandmanden trådte til da ilden spredte sig hurtigt.', 'Пожежник втрутився, коли вогонь швидко поширився.'), ('dreje af', 'phrase', '2e36f1e3-b6c2-50c7-ad36-ff91e4b5a773', 1, 'verb', null, 'звертати', 'Bilen drejede af ved næste vej.', 'Автомобіль звернув на наступну дорогу.'), ('foretage sig', 'phrase', 'bd97badb-7f51-5684-b2bc-f17369d3bf76', 1, 'verb', null, 'робити (чимось займатися)', 'Hvad vil du foretage dig i weekenden?', 'Чим ти хочеш зайнятися на вихідних?'), ('slutte sig til', 'phrase', 'ec8b9733-28ff-5a9d-8e97-4c6f2669ac97', 1, 'verb', null, 'приєднуватися (до групи, думки)', 'Jeg slutter mig til holdet i morgen.', 'Я приєднаюся до команди завтра.'), ('slippe op', 'phrase', '88ce702d-64f2-58dc-aee3-39e8da176838', 1, 'verb', null, 'закінчуватися (про запаси)', 'Mælken slap op i morges.', 'Молоко закінчилося сьогодні вранці.'), ('holde stand', 'phrase', 'a6d10047-4334-518c-b19b-56a6b0ef30f4', 1, 'verb', null, 'триматися, не здаватися', 'Soldaterne holdt stand mod fjenden hele natten.', 'Солдати тримали позиції проти ворога всю ніч.'), ('dække over', 'phrase', '5c57d1e5-fee0-5cdd-98a7-eeeccf3bb577', 1, 'verb', null, 'приховувати', 'Hans smil dækkede over en stor usikkerhed.', 'Його усмішка приховувала велику невпевненість.'), ('dække over', 'phrase', 'f82cc88e-6a36-529b-ac78-6bcaf66491ba', 2, 'verb', null, 'охоплювати (включати в значення)', 'Ordet ''dyr'' dækker over mange forskellige arter.', 'Слово «тварина» охоплює багато різних видів.'), ('ringe op', 'phrase', 'ab5a41f4-953d-5794-8784-098ec3d9fd9c', 1, 'verb', null, 'дзвонити (телефоном)', 'Jeg ringer op til min ven i aften.', 'Я подзвоню своєму другу сьогодні ввечері.'), ('varme op', 'phrase', '6df1da05-a28a-58b1-9750-e89a097ad693', 1, 'verb', null, 'розминатися (перед спортом)', 'Vi varmer op inden løbeturen.', 'Ми розминаємося перед пробіжкою.'), ('spare op', 'phrase', '2a632b31-f911-5f93-8ba1-53c3a2c05922', 1, 'verb', null, 'збирати (гроші)', 'Hun sparer op til en ny cykel.', 'Вона збирає гроші на новий велосипед.'), ('spare på', 'phrase', 'fd031481-92d5-583c-aa80-474b617a3003', 1, 'verb', null, 'економити (витрачати менше)', 'Vi sparer på vandet i tørkeperioder.', 'Ми економимо воду під час посухи.'), ('lave sjov', 'phrase', '93f0e368-e5aa-5939-8b06-2c38d6ac7c9f', 1, 'verb', null, 'жартувати, дуріти', 'Børnene laver sjov i haven hele dagen.', 'Діти дуріють у саду цілий день.'), ('drive forretning', 'phrase', '3c56373d-1c91-5390-901a-b63a5219febe', 1, 'verb', null, 'вести бізнес', 'Han driver forretning fra sit hjem.', 'Він веде бізнес з дому.'), ('træffe en beslutning', 'phrase', '03046b8c-a876-52bc-96dd-3a665db3f46c', 1, 'verb', null, 'ухвалювати рішення', 'Hun traf en beslutning om at flytte til byen.', 'Вона прийняла рішення переїхати до міста.'), ('flyve med', 'phrase', '962c8bce-1fa4-581a-8249-c24c1a8360a8', 1, 'verb', null, 'летіти (літаком) разом із кимось', 'Jeg flyver med min søster til London i morgen.', 'Завтра я лечу з сестрою до Лондона.'), ('snakke færdig', 'phrase', '0a6a6e86-a442-53f7-ba2f-d100a53dbb79', 1, 'verb', null, 'договорити', 'Vi snakkede færdig før mødet startede.', 'Ми закінчили розмову перед початком зустрічі.'), ('brænde sig', 'phrase', '34f01c88-fadf-52a8-a600-86129c99fdce', 1, 'verb', null, 'обпектися', 'Pas på, du kan brænde dig på den varme pande.', 'Будь обережний, можеш обпектися на гарячій сковороді.'), ('indgå fred', 'phrase', 'dd9357e4-1632-5cd1-95cb-f7467e0e9c86', 1, 'verb', null, 'укладати мир', 'De to lande indgik fred efter krigen.', 'Після війни дві країни уклали мир.'), ('ofre sig', 'phrase', 'a6b010cd-d920-5773-93f2-60feba98a4de', 1, 'verb', null, 'жертвувати собою', 'Hun ofrede sig for sin families skyld.', 'Вона пожертвувала собою заради своєї родини.'), ('være i brand', 'phrase', '8759cb13-6aca-5d9b-8b6d-8b5f05480915', 1, 'verb', null, 'горіти (про будівлю, предмет)', 'Bygningen er i brand, og brandvæsenet er på vej.', 'Будівля горить, і пожежники вже в дорозі.'), ('få bank', 'phrase', '0d220c1c-5916-50f8-a529-bc4212fb98e8', 1, 'verb', null, 'отримати прочухана', 'Han fik bank af de store drenge i skolegården.', 'Його побили великі хлопці на шкільному подвір''ї.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0009' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
